{"google_scholar": {"bibtex": "@article{taylor2007investigation,
 title={Investigation of metabolic myopathies},
 author={Taylor, RW and Chinnery, PF and Turnbull, DM},
 journal={Handbook of Clinical Neurology},
 volume={86},
 pages={193--204},
 year={2007},
 publisher={Elsevier}
 abstract = {Publisher Summary This chapter presents the investigation of metabolic myopathies. Glycogen storage disorders (the glycogenoses) are a group of rare inherited metabolic diseases},
}", "parsed": {"doi": null, "year": 2007, "gs_id": null, "pm_id": null, "title": "Investigation of metabolic myopathies", "authors": ["Taylor, RW", "Chinnery, PF", "Turnbull, DM"], "journal": "Handbook of Clinical Neurology", "abstract": "Publisher Summary This chapter presents the investigation of metabolic myopathies. Glycogen storage disorders (the glycogenoses) are a group of rare inherited metabolic diseases", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://www.sciencedirect.com/science/article/pii/S007297520786009X", "full_abstract": "Publisher Summary This chapter presents the investigation of metabolic myopathies. Glycogen storage disorders (the glycogenoses) are a group of rare inherited metabolic diseases due to abnormal synthesis or breakdown of glycogen. Most affect single cytoplasmic enzymes, with the exception of α-glucosidase (acid maltase) deficiency which involves the lysosomal glycogen degradation pathway. The glycogen storage disorders generally present clinically in one of two ways: exercise intolerance, muscle cramps and intermittent rhabdomyolysis, or progressive proximal weakness. Defects of mitochondrial oxidative phosphorylation are an important cause of muscle disease and are often described as mitochondrial myopathies. The biochemistry and genetics of these disorders are much more complex than either glycogen storage disorders or fatty acid oxidation, predominantly due to the involvement of the mitochondrial genome (mtDNA). In addition, mitochondrial oxidative phosphorylation disorders — all of which are characterized by the inability of the cell to produce enough ATP on account of respiratory chain dysfunction—may present with a vast array of different clinical features, which makes them enter the differential diagnosis of many different neurological conditions.", "abstract_snippet": "Publisher Summary This chapter presents the investigation of metabolic myopathies. Glycogen storage disorders (the glycogenoses) are a group of rare inherited metabolic diseases", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false}}

{"google_scholar": {"bibtex": "@article{ko2007agl,
 title={AGL gene mutation and clinical features in Korean patients with glycogen storage disease type III},
 author={Ko, Jung-Min and Kim, Gu-Hwan and Yoo, Han-Wook},
 journal={Journal of Genetic Medicine},
 pages={72--79},
 year={2007}
 abstract = {PURPOSE: Glycogen storage disease type III ( GSD - III ) is a in three unrelated Korean GSD - III patients, and characterizing of three unrelated Korean GSD - III patients by biochemical,},
}", "parsed": {"doi": null, "year": 2007, "gs_id": null, "pm_id": null, "title": "AGL gene mutation and clinical features in Korean patients with glycogen storage disease type III", "authors": ["Ko, Jung-Min", "Kim, Gu-Hwan", "Yoo, Han-Wook"], "journal": "Journal of Genetic Medicine", "abstract": "PURPOSE: Glycogen storage disease type III ( GSD - III ) is a in three unrelated Korean GSD - III patients, and characterizing of three unrelated Korean GSD - III patients by biochemical,", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://pesquisa.bvsalud.org/portal/resource/pt/wpr-33496", "full_abstract": "ABSTRACT PURPOSE: Glycogen storage disease type III (GSD-III) is a rare autosomal recessive disorder of glycogen metabolism. The affected enzyme, amylo-1,6-glucosidase, 4-alpha-glucanotransferase (AGL, glycogen debranching enzyme), is responsible for the debranching of the glycogen molecule during catabolism. The disease shows clinical and biochemical heterogeneity, reflecting genotype-phenotype heterogeneity among different patients. In this study, we aim at analyzing mutations of the AGL gene in three unrelated Korean GSD-III patients, and characterizing their clinical and laboratory findings. METHODS: We characterized the clinical features of three unrelated Korean GSD-III patients by biochemical, histological and imaging studies. The 35 exons and part of exon-intron boundaries of AGL were analyzed by direct sequencing using genomic DNA extracted from the peripheral leukocytes of patients. RESULTS: Diverse clinical features were observed in these patients including hepatomegaly (all patients), seizures (patient 2), growth failure (patients 1 and 2), hyperlipidemia (patients 1 and 3), raised transaminase and creatine kinase concentrations (all patients), and mild cardiomyopathy (patient 2). Liver transplantation was performed in patient 2 due to progressive hepatic fibrosis. Administration of uncooked corn starch maintained normoglycemia and improved biochemical and growth profiles. DNA sequence analysis revealed mutations in 5 out of 6 alleles. Patient 1 was a compound heterozygote of c.1282 G>A (p.R428K) and c.1306delA (p.S603PfsX6), patient 2 had c.1510_1511insT (p.Y504LfsX10), and patient 3 had c.3416 T>C (p.L1139P) and c.1735+1 G>T (p.Y538_R578delfsX4) mutations. Apart from the p.R428K mutation, the 4 other substitutions identified were novel. CONCLUSION: GSD-III patients display variable phenotypic characteristics resembling those of GSD-Ia. Molecular defects in the AGL gene of Korean GSD-III patients are genetically heterogeneous.", "abstract_snippet": "PURPOSE: Glycogen storage disease type III ( GSD - III ) is a in three unrelated Korean GSD - III patients, and characterizing of three unrelated Korean GSD - III patients by biochemical,", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

