}", "parsed": {"doi": null, "year": 2008, "gs_id": null, "pm_id": null, "title": "Glycogen storage disease type I in Tunisia: an epidemiological analysis", "authors": ["Chehida, A Ben", "Tebib, N", "Cherif, W", "Turkia, H Ben", "Abdelmoula, S", "Azzouz, H", "Ben Dridi, MF"], "journal": "Journal of Inherited Metabolic Disease: Official Journal of the Society for the Study of Inborn Errors of Metabolism", "abstract": "glycogen storage disease type I GSD III glycogen storage disease type III IEM by enzymatic assay: 1 GSD I and 13 GSD type III . All the patients studied originate from 3 governorates of", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://onlinelibrary.wiley.com/doi/abs/10.1007/s10545-008-0707-2", "full_abstract": "Summary Objective: Analysis of epidemiological data concerning GSD I in Tunisia. Subjects and methods: All the cases diagnosed as GSD I between 1992 and 2005 in a paediatric department recruiting all the metabolic diseases referred from the North of Tunisia were reviewed. Individual data (sex, socioeconomic and educational background, geographic origins, insurance coverage) were collected and pedigrees were reconstituted. Results: Twenty-two cases (9 boys and 13 girls from 20 homes) were identified. Fourteen belonged to 11 families originating from the North of Tunisia; ten of them are still alive. Both parents in 4 homes (21%) and one parent in 9 homes (47%) were illiterate. Most of the homes (60%) had a low income and 45% comprised at least 3 children. Only 7 homes (35%) had health insurance. Pedigrees indicated 44 infant deaths and at least 10 other cases fulfilling the clinical features of GSD I but not diagnosed. Conclusion: The paediatric prevalence of GSD I in the North of Tunisia can be estimated to 7.93 cases per one million inhabitants and its incidence to 1/100 000 births. However, it is likely to be more frequent because of underreporting or underdiagnosis leading to precocious deaths.", "abstract_snippet": "glycogen storage disease type I GSD III glycogen storage disease type III IEM by enzymatic assay: 1 GSD I and 13 GSD type III . All the patients studied originate from 3 governorates of", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

{"pubmed": {"issue": "2", "pages": "219-25", "source": "PubMed", "volume": "14", "medline": {"AB": "Glycogen storage disease type III (GSD III) is a very rare disorder caused by a deficiency in the activities of glycogen debranching enzymes (amylo-1-6-glucosidase and 4-alpha-glucanotransferase). GSD III is characterized by the accumulation of abnormal glycogen in the liver and skeletal muscle. The primary clinical manifestations are hepatomegaly, fasting hypoglycemia, and hyperlipidemia in infants. We report a rare case of GSD III in an adult. A 52-year-old woman presented to our clinic due to dyspnea on exertion, severe general weakness, and hepatomegaly. Hypertrophic cardiomyopathy was diagnosed based on echocardiogram findings. The microscopic findings of liver and skeletal muscle biopsies were consistent with the diagnosis of GSD. DNA analysis prompted by clinical and pathologic findings led to a definitive diagnosis of GSD IIIa. Diet therapy with cornstarch was started, and the patient was followed closely. This represents the first reported case of GSD IIIa diagnosed in an adult in Korea.", "AD": "Department of Internal Medicine, Yeungnam University College of Medicine, Daegu, Korea.", "AU": "Choi JH", "DP": "2008 Jun", "IP": "2", "IS": "1738-222X (Linking)", "JT": "The Korean journal of hepatology", "LA": "eng", "LR": "20080711", "MH": "Amino Acid Substitution; Base Sequence; Female; Glycogen Storage Disease Type III/*diagnosis/genetics/pathology; Hepatomegaly/genetics; Heterozygote; Humans; Liver/pathology; Middle Aged; Molecular Sequence Data; Muscle, Skeletal/pathology; Starch/therapeutic use; Tomography, X-Ray Computed", "PG": "219-25", "PL": "Korea (South)", "PT": "Case Reports; Journal Article", "RN": "9005-25-8 (Starch)", "SB": "IM", "SO": "Korean J Hepatol. 2008 Jun;14(2):219-25. doi: 10.3350/kjhep.2008.14.2.219.", "TA": "Korean J Hepatol", "TI": "An adult case of glycogen storage disease type IIIa.", "VI": "14", "AID": "200806219 [pii]; 10.3350/kjhep