{"google_scholar": {"bibtex": "@article{heller2008nutritional,
 title={Nutritional therapy for glycogen storage diseases},
 author={Heller, Solange and Worona, Liliana and Consuelo, Alejandra},
 journal={Journal of pediatric gastroenterology and nutrition},
 volume={47},
 pages={S15--S21},
 year={2008},
 publisher={Wiley Online Library}
 abstract = {There are 2 major subtypes of GSD type III : type IIIa, which affects both the liver and muscle and constitutes approximately 15\% of all GSD type III cases. Hepatomegaly, hypoglycemia,},
}", "parsed": {"doi": null, "year": 2008, "gs_id": null, "pm_id": null, "title": "Nutritional therapy for glycogen storage diseases", "authors": ["Heller, Solange", "Worona, Liliana", "Consuelo, Alejandra"], "journal": "Journal of pediatric gastroenterology and nutrition", "abstract": "There are 2 major subtypes of GSD type III : type IIIa, which affects both the liver and muscle and constitutes approximately 15\% of all GSD type III cases. Hepatomegaly, hypoglycemia,", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://onlinelibrary.wiley.com/doi/abs/10.1097/MPG.0b013e3181818ea5", "full_abstract": "ABSTRACT Glycogen storage diseases (GSDs) are a group of inherited disorders characterized by enzyme defects that affect the glycogen synthesis and degradation cycle, classified according to the enzyme deficiency and the affected tissue. The understanding of GSD has increased in recent decades, and nutritional management of some GSDs has allowed better control of hypoglycemia and metabolic complications. However, growth failure and liver, renal, and other complications are frequent problems in the long-term outcome. Hypoglycemia is the main biochemical consequence of GSD type I and some of the other GSDs. The basis of dietary therapy is nutritional manipulation to prevent hypoglycemia and improve metabolic dysfunction, with the use of continuous nocturnal intragastric feeding or cornstarch therapy at night and foods rich in starches with low concentrations of galactose and fructose during the day and to prevent hypoglycemia during the night.", "abstract_snippet": "There are 2 major subtypes of GSD type III : type IIIa, which affects both the liver and muscle and constitutes approximately 15% of all GSD type III cases. Hepatomegaly, hypoglycemia,", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

{"google_scholar": {"bibtex": "@incollection{ichida2009primary,
 title={Primary metabolic and renal hyperuricemia},
 author={Ichida, Kimiyoshi and Hosoyamada, Makoto and Hosoya, Tatsuo and Endou, Hitoshi},
 booktitle={Genetic Diseases of the Kidney},
 pages={651--660},
 year={2009},
 publisher={Elsevier}
 abstract = {Publisher Summary This chapter focuses on purine metabolism and the purine metabolic enzyme disorders, Lesch-Nyhan syndrome and pyrophosphate synthetase (PRPS)},
}", "parsed": {"doi": null, "year": 2009, "gs_id": null, "pm_id": null, "title": "Primary metabolic and renal hyperuricemia", "authors": ["Ichida, Kimiyoshi", "Hosoyamada, Makoto", "Hosoya, Tatsuo", "Endou, Hitoshi"], "journal": "Genetic Diseases of the Kidney", "abstract": "Publisher Summary This chapter focuses on purine metabolism and the purine metabolic enzyme disorders, Lesch-Nyhan syndrome and pyrophosphate synthetase (PRPS)", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://www.sciencedirect.com/science/article/pii/B9780124498518000383", "full_abstract": "Publisher Summary This chapter focuses on purine metabolism and the purine metabolic enzyme disorders, Lesch-Nyhan syndrome and pyrophosphate synthetase (PRPS) superactivity. It also discusses other single gene disorders such as glycogen storage disease types I and VII and the underexcretion type hyperuricemia, familial juvenile hyperuricemic nephropathy. Renal underexcretion is the main mechanism for the development of primary hyperuricemia in most patients, even in the overproduction type patients without genetic disorders. Lesch-Nyhan disease is the most common cause of hyperuricemia in infancy and childhood and the frequency approximates one in 3,80,000 births. The clinical manifestations of Lesch-Nyhan disease include urolithiasis or gout due to uric acid overproduction and overexcretion, mental and growth retardation, choreoathetosis, dystonia, compulsive self-injurious behavior, and sometimes, megaloblastic anemia. Infants with Lesch-Nyhan disease appear normal at birth and usually develop normally for the first 3-8 months. The majority of patients with Lesch-Nyhan disease are recognized when they are between 3 and 12 months of age with motor disability or hypotonia. Extrapyramidal signs such as choreoathetosis and dystonia and pyramidal signs such as hyperreflexia and extensor plantar reflex typically begin to develop between 1 and 2 years of age. PRPS overactivity is an X-linked recessive disorder and only a small number of point mutations in PRPSl have been identified in patients with PRPS overactivity. The clinical manifestations of PRPS overactivity include urolithiasis or gout due to hyperuricemia and hyperuricosuria similar to HPRT deficiency, and neurological deficits frequently including sensorineural deafness.Patients with the greater severity show symptoms such as sensorineural deafness, cerebellar ataxia, muscular hypotonia, mental and motor retardation since early childhood, and signs of uric acid overproduction.", "abstract_snippet": "Publisher Summary This chapter focuses on purine metabolism and the purine metabolic enzyme disorders, Lesch-Nyhan syndrome and pyrophosphate synthetase (PRPS)", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

