}", "parsed": {"doi": null, "year": 2010, "gs_id": null, "pm_id": null, "title": "Glycogen storage diseases", "authors": ["Chen, Mingyi"], "journal": "Molecular pathology of liver diseases", "abstract": "Type III GSD (debrancher deficiency, limit dextrinosis ) is caused by deficiency of glycogen The splice mutation IVS32-12A > G is found in GSD - III patients having mild clinical symptoms,", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://link.springer.com/chapter/10.1007/978-1-4419-7107-4_45", "full_abstract": "Glycogen is a branched polymer of glucose, which serves as a reservoir of glucose units. The two largest deposits in mammals are in the liver and skeletal muscle but many cells are capable of synthesizing glycogen. Its accumulation and utilization are under elaborate control by a variety of enzymes.", "abstract_snippet": "Type III GSD (debrancher deficiency, limit dextrinosis ) is caused by deficiency of glycogen The splice mutation IVS32-12A > G is found in GSD - III patients having mild clinical symptoms,", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false}}

{"pubmed": {"issue": "1", "pages": "41-5", "source": "PubMed", "volume": "69", "medline": {"AB": "The confirmation of type III glycogen storage disease diagnosis is based on histological explorations on to live and/or muscle biopsies that induce some problems of delay and sensitivity. The purpose of this study was to evaluate a fluorimetric technique for the determination of amylo-1,6-glucosidase activity in leukocytes, in order to confirm the diagnosis of type III glycogen storage disease. The method consists in measuring the glucose released by hydrolysis of phosphorylase dextrin limit in the presence of cellular extracts, in 50 volunteers and 18 patients suspected of glycogenosis. Benefits of this technique are linearity, precision (CV = 1.68%), exactitude (CI = 0.17%), its high sensitivity (Sn = 100%) and its specificity (Sp = 96.1%). The phosphorylation of dextrin limit test allows measurement of both transferasic (alpha-1,4) and hydrolytic (alpha-1,6) enzyme activities. In conclusion, this non-invasive, and inexpensive assay, can be applied to most of the clinical biology laboratories. Comparison with radiometry and immunoblot indicate a noticeable discriminating capacity between normal subjects, patients with type I and VI glycogenosis, and patients' subgroups of type III glycogenosis.", "AD": "Faculte de medecine lbn El Jazzar, Sousse, Tunisie. hanene_as@yahoo.fr", "AU": "Limem K", "DP": "2011 Jan-Feb", "IP": "1", "IS": "0003-3898 (Linking)", "JT": "Annales de biologie clinique", "LA": "fre", "LR": "20110405", "MH": "Adolescent; Adult; Child; Child, Preschool; Female; Fluorometry; Glycogen Debranching Enzyme System/*metabolism; Glycogen Storage Disease Type III/*diagnosis; Humans; Infant; Leukocytes/*enzymology; Male; Young Adult", "PG": "41-5", "PL": "France", "PT": "English Abstract; Journal Article", "RN": "EC 3.2.1.33 (amylo-1,6-glucosidase)", "SB": "IM", "SO": "Ann Biol Clin (Paris). 2011 Jan-Feb;69(1):41-5. doi: 10.1684/abc.2010.0514.", "TA": "Ann Biol