d": 282, "begin": 278, "content": "278-282", "page_count": 5}, "issue": 4, "pubtype": "Journal", "pubyear": 2012, "pubmonth": "DEC", "sortdate": "2012-12-01", "coverdate": "DEC 2012", "has_abstract": "Y", "journal_oas_gold": "N"}, "publishers": {"publisher": {"names": {"name": {"role": "publisher", "seq_no": 1, "addr_no": 1, "full_name": "GALENOS YAYINCILIK", "display_name": "GALENOS YAYINCILIK", "unified_name": "Galenos Yayincilik"}, "count": 1}, "address_spec": {"city": "FINDIKZADE", "addr_no": 1, "full_address": "MOLLA GURANI CAD 22-2, FINDIKZADE, ISTANBUL 34093, TURKEY"}}}}, "contributors": {"count": 3, "contributor": [{"name": {"r_id": "AAI-8259-2020", "role": "researcher_id", "seq_no": 1, "spPGUID": "urn:spm:1971842", "orcid_id": "0000-0001-6114-9210", "daisng_id": 1971842, "full_name": "ARTAN, REHA", "last_name": "ARTAN", "first_name": "REHA", "display_name": "ARTAN, REHA"}}, {"name": {"r_id": "AGH-4534-2022", "role": "researcher_id", "seq_no": 2, "spPGUID": "urn:spm:3783288", "orcid_id": "0000-0003-3257-7798", "daisng_id": 3783288, "full_name": "Uygun, Vedat", "last_name": "Uygun", "first_name": "Vedat", "display_name": "Uygun, Vedat"}}, {"name": {"r_id": "C-2408-2016", "role": "researcher_id", "seq_no": 3, "spPGUID": "urn:spm:1229252", "daisng_id": 1229252, "full_name": "manguoglu, esra", "last_name": "manguoglu", "first_name": "esra", "display_name": "manguoglu, esra"}}]}, "fullrecord_metadata": {"refs": {"count": 21}, "keywords": {"count": 3, "keyword": ["AGL gene", "glycogen storage disease type III", "mutation"]}, "abstracts": {"count": 1, "abstract": {"abstract_text": {"p": ["Aim: AGL gene mutations are responsible for glycogen storage disease type Ill which is an autosomal recessive disorder. The distribution of these mutations shows a great variance in different populations. The aim of this study is to uncover the AGL gene mutation profile among Turkish patients and to contribute to the establishment of a link between these mutations and the clinical picture of the disease.", "Material and Method: A total of ten patients aged between two and eight years (mean age 1.7+1.1) who were diagnosed with glycogen storage disease type III by liver biopsy and enzymatic analysis from eight different families were included in this study. DNA was isolated from the peripheral blood samples of these patients and exons 6, 7, 9-18, 22, 24, 29-34 of the AGL gene were studied by DNA sequencing analysis.", "Results: Our study revealed two novel missense mutations p.G167V and p.Y173E two novel intronic single base substitutions c.1284-1G>A and c.2002-2A>T and a known single base substitution p.W1327X. Numerous intronic variants were also identified. As a result of the analysis of ten patients, SNP's rs3736296, IVS12-197T>G, rs2291637, rs2035961, rs2274570, rs6692695, rs296885 were found in 1, 6, 1, 1, 1, 1, and 2 of the 10 patients, respectively.", "Conclusions: According to the recent literature about the AGL gene which is constituted of a total of 35 coding exons, mutations have been reported frequently in exons 3, 4, 7, 16, 21, 25, 30 and 31. This study and previous studies reveal that the majority of the mutations identified in Turkish patients so far have been detected in exon 31 of the AGL gene. In addition, the distribution of AGL gene mutations in Turkish patients reflects the genetic heterogeneity in our population. (Turk Arch Ped 2012; 47:278-82)"], "count": 4}}}, "addresses": {"count": 2, "address_name": [{"names": {"name": [{"role": "author", "seq_no": 1, "addr_no": 1, "daisng_id": 1229252, "full_name": "Manguoglu, Esra", "last_name": "Manguoglu", "first_name": "Esra", "claim_status": true, "display_name": "Manguoglu, Esra", "wos_standard": "Manguoglu, E", "data-item-ids": {"data-item-id": [{"type": "person", "content": "C-2408-2016", "id-type": "PreferredRID"}, {"type": "person", "content": "0000-0002-6214-622X", "id-type": "PreferredORCID"}, {"type": "person", "content": "0000-0002-6214-622X", "id-type": "OtherORCID"}]}, "preferred_name": {"full_name": "manguoglu, esra ayse", "last_name": "manguoglu", "first_name": "esra", "middle_name": "ayse"}}, {"role": "author", "seq_no": 3, "addr_no": 1, "daisng_id": 12372114, "full_name": "Ozkaya, Figen", "last_name": "Ozkaya", "first_name": "Figen", "claim_status": false, "display_name": "Ozkaya, Figen", "wos_standard": "Özkaya, F", "data-item-ids": {"data-item-id": {"type": "person", "content": "DJL-1711-2022", "id-type": "PreferredRID"}}, "preferred_name": {"full_name": "Ozkaya, Figen", "last_name": "Ozkaya", "first_name": "Figen"}}, {"role": "author", "seq_no": 4, "addr_no": 1, "daisng_id": 11834963, "full_name": "Luleci, Guven", "last_name": "Luleci", "first_name": "Guven", "claim_status": false, "display_name": "Luleci, Guven", "wos_standard": "Lüleci, G", "data-item-ids": {"data-item-id": {"type": "person", "content": "DGY-4560-2022", "id-type": "PreferredRID"}}, "preferred_name": {"full_name": "Luleci, Guven", "last_name": "Luleci", "first_name": "Guven"}}, {"role": "author", "seq_no": 6, "addr_no": 1, "daisng_id": 19920154, "full_name": "Berker, Sibel", "last_name": "Berker", "first_name": "Sibel", "claim_status": false, "display_name": "Berker, Sibel", "wos_standard": "Berker, S", "data-item-ids": {"data-item-id": {"type": "person", "content": "EOL-9756-2022", "id-type": "PreferredRID"}}, "preferred_name": {"full_name": "Berker, Sibel", "last_name": "Berker", "first_name": "Sibel"}}], "count": 4}, "address_spec": {"zip": {"content": "TR-07058", "location": "BC"}, "city": "Antalya", "addr_no": 1, "country": "Turkey", "orig_seq": 1, "full_address": "Akdeniz Univ, Tip Fak, Tibbi Biyol Anabilim Dali, TR-07058 Antalya, Turkey", "organizations": {"count": 2, "organization": [{"pref": null, "content": "Akdeniz Univ"}, {"pref": "Y", "level": 0, "ror_id": "https://ror.org/01m59r132", "content": "Akdeniz University", "hierarchy_type": "incites"}]}, "suborganizations": {"count": 2, "suborganization": ["Tip Fak", "Tibbi Biyol Anabilim Dali"]}