}", "parsed": {"doi": null, "year": 2012, "gs_id": null, "pm_id": null, "title": "The glycogen storage diseases and related disorders", "authors": ["Laforet, Pascal", "Weinstein, David A", "Peter A. Smit, G"], "journal": "Inborn metabolic diseases: diagnosis and treatment", "abstract": "The liver GSDs comprise GSD I, the hepatic presentations of GSD III , Patients with GSD III have a syndrome that includes The muscle forms of GSD III and -IX are also discussed in this", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://link.springer.com/content/pdf/10.1007/978-3-642-15720-2_6?pdf=chapter%20toc", "full_abstract": "The liver GSDs comprise GSD I, the hepatic presentations of GSD III, GSD IV, GSD VI, the liver forms of GSD IX, and GSD 0. GSD I, -III, -VI, and -IX present with hypoglycaemia, marked hepatomegaly, and retarded growth [6]. GSD I is the most severe of these four conditions, because both glycogenolysis and gluconeogenesis are impaired. Patients with GSD III have a syndrome that includes hepatopathy, myopathy and often cardiomyopathy. Unlike the other hepatic forms of GSD, GSD IV usually manifests in infancy or childhood as hepatic failure with cirrhosis leading to end-stage liver disease. GSD VI and the hepatic forms of GSD IX are classically the mildest forms, but there is recent evidence that optimised therapy decreases the rate of liver pathology and improves growth.", "abstract_snippet": "The liver GSDs comprise GSD I, the hepatic presentations of GSD III , Patients with GSD III have a syndrome that includes The muscle forms of GSD III and -IX are also discussed in this", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false}}

